use std::env;use std::net::{IpAddr,SocketAddr,TcpStream};use std::time::Duration;
fn scope(s:&str)->String{match s.parse::<IpAddr>(){Ok(IpAddr::V4(x)) if x.is_private()||x.is_loopback()||x.is_link_local()=>"local/intranet".into(),Ok(IpAddr::V6(x)) if x.is_loopback()||x.is_unique_local()||x.is_unicast_link_local()=>"local/intranet".into(),Ok(_)=>"public".into(),Err(_)=>"invalid".into()}}
fn main(){let p:u16=env::var("NETWORK_API_PORT").ok().and_then(|x|x.parse().ok()).unwrap_or(8787);println!(r#"{{"schema":"bizx.network.api.v1","implementation":"rust","port":{},"endpoints":["catalog","health","config","interfaces","classify","authorize","tcp-check"]}}"#,p);println!("scope 127.0.0.1 = {}",scope("127.0.0.1"));let a="127.0.0.1:8787".parse::<SocketAddr>().unwrap();println!("local API port reachable = {}",TcpStream::connect_timeout(&a,Duration::from_secs(1)).is_ok());}
